nav=[('◫','Overview','overview'),('◉','Servers / IPs','servers'),('▣','Nodes','nodes'),('◎','Players','players'),('◇','License review','reviews'),('≋','Activity log','activity'),('⚙','Settings','settings')]
def shell(title,active,body):
 links=''.join(f'<a class="nav-link {"selected" if key==active else ""}"><i>{icon}</i>{label}</a>' for icon,label,key in nav)
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ArkFlame DRM v0.5.4 illustrative preview · {escape(title)}</title><style>{style}</style></head><body><div class="frame"><aside class="sidebar"><div class="brand"><span class="brand-icon">♨</span><div><strong>ARKFLAME</strong><small>DRM CONTROL CENTER</small></div></div><div class="nav-caption">WORKSPACE</div>{links}<div class="nav-foot"><b>◇ DATA POLICY</b><p>Unverified node telemetry. Reviews are advisory; no automated enforcement.</p></div><div class="signout">↪ Sign out</div></aside><header class="topbar"><div class="crumb"><span class="mobile-menu">☰ &nbsp;</span><small>WORKSPACE &nbsp; ›</small>{escape(title)}</div><div class="topright"><span class="online-status"><span class="online-dot"></span>Auto-refresh · 30s</span><span class="refresh" title="Refresh data">↻</span><span class="topbar-divider"></span><a class="avatar" href="/settings" title="Open settings">A</a></div></header><main class="content">{body}<div class="footer">© ArkFlame · Private analytics workspace &nbsp; · &nbsp; Protocol v2 / Advisory mode</div></main></div><div class="demo-label">ILLUSTRATIVE PREVIEW · SAMPLE DATA · NOT LIVE TELEMETRY</div></body></html>'''
def head(eye,title,description,button=''):
 return f'<div class="heading"><div><div class="eyebrow">{eye}</div><h1>{title}</h1><p>{description}</p></div>{"<span class=action>"+button+" →</span>" if button else ""}</div>'
def metric(label,num,hint,tone='',icon=''):
 return f'<div class="panel metric-card metric-{tone}"><div class="metric-top"><span>{label}</span><span class="metric-icon">{icon}</span></div><div class="metric-number">{num}</div><div class="metric-hint">{hint}</div></div>'
def section(title,sub,content,action=''):
 return f'<section class="section panel"><div class="section-header"><div><div class="section-title">{title}</div><div class="section-subtitle">{sub}</div></div>{"<span class=section-link>"+action+" →</span>" if action else ""}</div>{content}</section>'
def table(headers,rows):
 return '<div class="table-wrap"><table class="table"><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def chart():
 points=289; maxp=150; maxs=45; left=58;right=939;top=28;bottom=246
 xy=lambda i,v,m:(left+(right-left)*i/(points-1),bottom-v/m*(bottom-top))
 players=[round(88+38*sin(i/34)+15*cos(i/11)) for i in range(points)]
 servers=[round(24+9*sin(i/45)+3*cos(i/13)) for i in range(points)]
 base=datetime(2026,10,10,18,30,tzinfo=timezone.utc)
 svg=['<svg class="chart-svg" viewBox="0 0 1000 300" role="img" aria-label="Sample online players left axis and servers right axis">', '<defs><linearGradient id="pgrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#87aaff" stop-opacity=".19"/><stop offset="1" stop-color="#87aaff" stop-opacity="0"/></linearGradient><linearGradient id="sgrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#65e4af" stop-opacity=".11"/><stop offset="1" stop-color="#65e4af" stop-opacity="0"/></linearGradient></defs>']
 for tick in range(5):
  t=tick/4;y=bottom-t*(bottom-top)
  svg.extend([f'<line x1="{left}" x2="{right}" y1="{y}" y2="{y}" stroke="#b8c8ee" stroke-opacity=".14" stroke-dasharray="3 6"/>',f'<text x="{left-12}" y="{y+4}" text-anchor="end" fill="#a9bded" font-size="11">{round(maxp*t)}</text>',f'<text x="{right+12}" y="{y+4}" text-anchor="start" fill="#80cba9" font-size="11">{round(maxs*t)}</text>'])
 for tick in range(5):
  i=round((points-1)*tick/4);x=left+(right-left)*tick;t=(base+timedelta(minutes=5*i)).strftime('%H:%M')
  anchor='start' if tick==0 else 'end' if tick==4 else 'middle'
  svg.append(f'<text x="{x}" y="282" text-anchor="{anchor}" fill="#9caec7" font-size="11">{t}</text>')
 for vals,maxval,color,gradient in [(players,maxp,'#87aaff','pgrad'),(servers,maxs,'#65e4af','sgrad')]:
  path=' '.join(f'{"M" if i==0 else "L"}{xy(i,v,maxval)[0]:.2f},{xy(i,v,maxval)[1]:.2f}' for i,v in enumerate(vals))
  area=path+f' L{right},{bottom} L{left},{bottom} Z'
  svg.extend([f'<path d="{area}" fill="url(#{gradient})"/>',f'<path d="{path}" stroke="{color}" stroke-width="2.8" fill="none" stroke-linejoin="round" stroke-linecap="round"/>'])
 svg.append('</svg>')
 chartTop=f'<div class="chart-summary"><div class="chart-stat"><span class="chart-stat-label"><i class="chart-dot chart-dot-player"></i>Players online <small>left axis</small></span><strong class="chart-stat-number" style="color:#a8bfff">{players[-1]}</strong></div><div class="chart-stat"><span class="chart-stat-label"><i class="chart-dot chart-dot-server"></i>Servers online <small>right axis</small></span><strong class="chart-stat-number" style="color:#78e5b4">{servers[-1]}</strong></div><div class="chart-sample"><span>18:30 UTC</span><small>289 of 289 intervals observed</small></div></div>'
 return '<div class="chart-content">'+chartTop+'<div class="chart-viewport">'+''.join(svg)+'</div><div class="chart-note">Rolling 24h · Five-minute UTC intervals · Missing samples are gaps, not zero · Arrow keys inspect observations · Independent labeled Y-axes</div></div>'
warning='<div class="notice">⚠ &nbsp; Telemetry arrives only from opted-in servers. Shared IPs do not establish ownership. BLOCK labels are advisory and are never automatically enforced.</div>'
metrics='<div class="overview-primary-grid">'+metric('Online nodes','31','68% of observed nodes','green','↗')+metric('Player connections','846','Reported online connections across nodes','blue','◎')+metric('Review markers','7','Suspicious filenames; verify manually','red','◇')+metric('Known nodes','46','Observed distinct node identities','','▣')+'</div>'
ctx='<div class="overview-context"><span>◉ &nbsp;<strong>18</strong> observed network IPs</span><span>▣ &nbsp;<strong>63</strong> product installations</span><span class="overview-disclaimer">Player counts are telemetry estimates, not independent reachability checks.</span></div>'
netRows=[('198.51.100.42','12','9','<span class="tag bad">3 flagged</span>','<span class="tag">REVIEW</span>'),('203.0.113.17','8','6','<span class="tag bad">2 flagged</span>','<span class="muted">NONE</span>'),('192.0.2.118','5','4','<span class="tag bad">2 flagged</span>','<span class="tag">ALLOW</span>'),('203.0.113.56','3','3','<span class="muted">0</span>','<span class="muted">NONE</span>')]
