nodesRows=[('e3f1c8a2…','198.51.100.42','FairPlay, FlameOrders','2m ago','<span class="tag bad">2 flagged</span>','<span class="green">● ONLINE</span>'),('c8d29e74…','203.0.113.17','ExploitFixer','3m ago','<span class="tag bad">1 flagged</span>','<span class="green">● ONLINE</span>'),('1b91f21d…','192.0.2.118','FlameStore, FairPlay','5m ago','<span class="muted">0</span>','<span class="green">● ONLINE</span>')]
overview=head('Network intelligence / 01','Fleet overview','Connected Minecraft nodes, observed networks and ArkFlame product installations. All telemetry is provisional until entitlement and endpoint identity are verified.','Explore nodes')+warning+metrics+ctx+section('Live activity · last 24 hours','Opt-in players and nodes · independent labeled scales · five-minute samples',chart())+'<div class="twocol">'+net+fleet+'</div>'+section('Recently observed nodes','Latest product sessions; live state updates approximately every 30 seconds.',table(['Node identity','Transport IP','Products','Last report','Suspect markers','Status'],nodesRows),'Browse nodes')
(root/'overview.html').write_text(shell('Overview','overview',overview))
