nodeTop='<div class="node-grid">'+section('Node information','<br>','<div class="key-list">'+''.join(f'<div class="pair"><span>{k}</span><b>{v}</b></div>' for k,v in [('IP address','198.51.100.42'),('Minecraft port','25565'),('Server version','Paper 1.21.4'),('Max players','120'),('Last seen','11 Oct, 18:30 UTC')])+'</div>')+section('Runtime health','Recent heartbeat snapshot','<div class="key-list">'+''.join(f'<div class="pair"><span>{k}</span><b>{v}</b></div>' for k,v in [('Status','<span class="green">● ONLINE</span>'),('Estimated uptime','98.2%'),('Active products','FairPlay, FlameOrders'),('Current players','46'),('Review markers','<span class="red">2</span>')])+'</div>')+section('Review decision','Node-level advisory override','<div style="padding:20px"><span class="muted">Effective policy</span> <span class="tag">REVIEW</span><p style="color:#9cabc1">Manually review observed plugin names and JAR files before assigning a label.</p><div class="action" style="display:inline-block">Update label</div></div>')+'</div>'
